def _calculate_single_mol_fingerprint(self, mol: Mol) -> np.ndarray:
    from rdkit.Chem.rdCIPLabeler import AssignCIPLabels

    if self.include_chirality:
        AssignCIPLabels(mol)

    atoms_envs = self._get_atom_envs(mol)
    shinglings = self._get_atom_pair_shingles(mol, atoms_envs)
    hashes = [self._hash_shingle(shingling) for shingling in shinglings]

    if self.variant == "minhash":
        return self._minhash(hashes)

    folded = np.zeros(
        self.fp_size,
        dtype=np.uint32 if self.variant == "count" else np.uint8,
    )
    for hashed in hashes:
        index = hashed % self.fp_size
        if self.variant == "count":
            folded[index] += 1
        else:
            folded[index] = 1
    return folded

@staticmethod
def _hash_shingle(shingling: bytes) -> int:
    # unique mapping from shingle strings to 32-bit integers, as used by
    # the original MAP4 and MAPC implementations
    return int(sha1(shingling).hexdigest()[:8], 16)

def _minhash(self, hashes: list[int]) -> np.ndarray:
    max_hash = (1 << 32) - 1

    if not hashes:
        return np.zeros(self.fp_size, dtype=np.uint32)

    if isinstance(self.random_state, np.random.RandomState):
        rng = self.random_state
    else:
        rng = np.random.RandomState(self.random_state)

    permutations = np.stack(
        [
            rng.randint(1, max_hash, size=self.fp_size, dtype=np.uint64),
            rng.randint(0, max_hash, size=self.fp_size, dtype=np.uint64),
        ],
        axis=1,
    )
    hashes = np.asarray(hashes, dtype=np.uint64)

    minhash = np.empty(self.fp_size, dtype=np.uint64)
    for idx, (a, b) in enumerate(permutations):
        minhash[idx] = np.min((a * hashes + b) % max_hash)

    return minhash.astype(np.uint32)

